style.css:
@-moz-document url-prefix("https://docs.google.com/spreadsheets/u/0/") {
/* Background of the grid */
    .grid-container {
        background-color: #FDE2E4 !important;
    }

    /* Top toolbar */
    .docs-menubar,
    .docs-titlebar {
        background-color: #FADADD !important;
    }

    /* Sidebars and tool panels */
    .docs-sidebar,
    .docs-explore-widget {
        background-color: #FCE1E4 !important;
    }

    /* Sheet tabs */
    .goog-tab-bar .goog-tab {
        background-color: #FADADD !important;
        color: #D6336C !important;
        font-weight: bold;
    }

    .goog-tab-bar .goog-tab-selected {
        background-color: #FBC4C4 !important;
        color: #FFFFFF !important;
    }

    /* Text color in grid */
    .cell-input {
        color: #D6336C !important;
    }

    /* Buttons */
    .goog-toolbar-button {
        background-color: #FAC1BE !important;
        color: white !important;
        border-radius: 8px !important;
    }

    /* Cute font for everything */
    body, input, textarea {
        font-family: "Comic Sans MS", "Comic Neue", cursive !important;
    }
}
